-- =====================================================================
-- Duka Marketplace :: 001_init (up)
-- PostgreSQL 18 (uses native uuidv7()).
-- Conventions
--   * ids          : uuid, generated by uuidv7() (never sequential integers)
--   * money        : bigint minor units + currency char(3) beside it, always
--   * timestamps   : timestamptz, created_at / updated_at on every mutable table
--   * soft delete  : deleted_at on PII-bearing tables that must be erasable
--   * SQLSTATEs    : DK001 illegal transition, DK002 immutable record,
--                    DK003 business rule violated
-- =====================================================================
BEGIN;

-- ---------- enums (closed sets; a new value is a migration, on purpose)
CREATE TYPE seller_status  AS ENUM ('pending_review', 'active', 'suspended');
CREATE TYPE listing_status AS ENUM ('draft', 'active', 'paused');
CREATE TYPE order_status   AS ENUM ('pending_payment', 'paid', 'shipped', 'delivered',
                                    'completed', 'cancelled', 'refunded');
CREATE TYPE payment_status AS ENUM ('pending', 'authorized', 'captured', 'failed',
                                    'voided', 'refunded');
CREATE TYPE actor_kind     AS ENUM ('buyer', 'seller', 'system', 'staff');

-- ---------- shared trigger helpers
CREATE FUNCTION set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;

-- Data-driven state machines: one row per ALLOWED transition. Anything
-- not listed is forbidden. Adding a transition is a data change that shows
-- up in code review; there is no status logic scattered through the app.
CREATE TABLE state_transitions (
  entity      text NOT NULL CHECK (entity IN ('order', 'payment', 'listing')),
  from_status text NOT NULL,
  to_status   text NOT NULL,
  PRIMARY KEY (entity, from_status, to_status),
  CONSTRAINT state_transitions_not_self CHECK (from_status <> to_status)
);

INSERT INTO state_transitions (entity, from_status, to_status) VALUES
  ('order', 'pending_payment', 'paid'),
  ('order', 'pending_payment', 'cancelled'),
  ('order', 'paid',            'shipped'),
  ('order', 'paid',            'cancelled'),
  ('order', 'shipped',         'delivered'),
  ('order', 'delivered',       'completed'),
  ('order', 'delivered',       'refunded'),
  ('payment', 'pending',    'authorized'),
  ('payment', 'pending',    'captured'),
  ('payment', 'pending',    'failed'),
  ('payment', 'authorized', 'captured'),
  ('payment', 'authorized', 'voided'),
  ('payment', 'captured',   'refunded'),
  ('listing', 'draft',  'active'),
  ('listing', 'active', 'paused'),
  ('listing', 'paused', 'active');

CREATE FUNCTION assert_transition(p_entity text, p_from text, p_to text) RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
  IF p_from IS DISTINCT FROM p_to AND NOT EXISTS (
       SELECT 1 FROM state_transitions
        WHERE entity = p_entity AND from_status = p_from AND to_status = p_to) THEN
    RAISE EXCEPTION 'illegal % transition: % -> %', p_entity, p_from, p_to
      USING ERRCODE = 'DK001';
  END IF;
END $$;

-- Rows may only be born in their initial state (no INSERT ... status='completed').
CREATE FUNCTION enforce_initial_status() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status::text <> TG_ARGV[0] THEN
    RAISE EXCEPTION '% must be created as %, not %', TG_TABLE_NAME, TG_ARGV[0], NEW.status
      USING ERRCODE = 'DK001';
  END IF;
  RETURN NEW;
END $$;

-- ---------- users (identity + PII) ----------------------------------
CREATE TABLE users (
  id          uuid PRIMARY KEY DEFAULT uuidv7(),
  email       text,
  full_name   text,
  phone_e164  text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  deleted_at  timestamptz,
  CONSTRAINT users_email_format CHECK (email IS NULL OR email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
  CONSTRAINT users_phone_format CHECK (phone_e164 IS NULL OR phone_e164 ~ '^\+[1-9][0-9]{7,14}$'),
  -- PII is mandatory for a live account and is nulled on erasure, nothing in between.
  CONSTRAINT users_pii_present_unless_erased CHECK (
    deleted_at IS NOT NULL
    OR (email IS NOT NULL AND full_name IS NOT NULL AND char_length(btrim(full_name)) BETWEEN 1 AND 120)),
  CONSTRAINT users_timestamps_ordered CHECK (updated_at >= created_at)
);
CREATE UNIQUE INDEX users_email_live_uq ON users (lower(email)) WHERE deleted_at IS NULL;
CREATE TRIGGER users_updated_at BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------- addresses (user 1:N) ------------------------------------
CREATE TABLE addresses (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  user_id         uuid NOT NULL REFERENCES users (id),
  recipient_name  text NOT NULL CHECK (char_length(recipient_name) BETWEEN 1 AND 120),
  line1           text NOT NULL CHECK (char_length(line1) BETWEEN 1 AND 200),
  line2           text,
  city            text NOT NULL,
  region          text,
  postal_code     text NOT NULL,
  country         char(2) NOT NULL CHECK (country ~ '^[A-Z]{2}$'),
  phone_e164      text CHECK (phone_e164 IS NULL OR phone_e164 ~ '^\+[1-9][0-9]{7,14}$'),
  is_default      boolean NOT NULL DEFAULT false,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  deleted_at      timestamptz,
  CONSTRAINT addresses_id_user_uq UNIQUE (id, user_id),     -- target for "address belongs to buyer" FK
  CONSTRAINT addresses_timestamps_ordered CHECK (updated_at >= created_at)
);
CREATE UNIQUE INDEX addresses_one_default_per_user ON addresses (user_id)
  WHERE is_default AND deleted_at IS NULL;
CREATE INDEX addresses_user_live_idx ON addresses (user_id) WHERE deleted_at IS NULL;
CREATE TRIGGER addresses_updated_at BEFORE UPDATE ON addresses FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------- sellers (0..1 per user) ---------------------------------
CREATE TABLE sellers (
  id          uuid PRIMARY KEY DEFAULT uuidv7(),
  user_id     uuid NOT NULL UNIQUE REFERENCES users (id),   -- UNIQUE makes the relationship 1:0..1
  shop_name   text NOT NULL CHECK (char_length(btrim(shop_name)) BETWEEN 2 AND 80),
  shop_slug   text NOT NULL CHECK (shop_slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  currency    char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),   -- the one currency this shop prices and settles in
  flat_shipping_fee_minor bigint NOT NULL DEFAULT 0 CONSTRAINT sellers_shipping_fee_nonneg CHECK (flat_shipping_fee_minor >= 0),
  status      seller_status NOT NULL DEFAULT 'pending_review',
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  deleted_at  timestamptz,
  CONSTRAINT sellers_id_currency_uq UNIQUE (id, currency),
  CONSTRAINT sellers_timestamps_ordered CHECK (updated_at >= created_at)
);
CREATE UNIQUE INDEX sellers_slug_live_uq ON sellers (shop_slug) WHERE deleted_at IS NULL;
CREATE TRIGGER sellers_updated_at BEFORE UPDATE ON sellers FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------- categories (self-referencing tree) ----------------------
CREATE TABLE categories (
  id          uuid PRIMARY KEY DEFAULT uuidv7(),
  parent_id   uuid REFERENCES categories (id),
  name        text NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 80),
  slug        text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  is_active   boolean NOT NULL DEFAULT true,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT categories_not_own_parent CHECK (parent_id IS NULL OR parent_id <> id),
  CONSTRAINT categories_timestamps_ordered CHECK (updated_at >= created_at)
);
CREATE TRIGGER categories_updated_at BEFORE UPDATE ON categories FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------- listings -------------------------------------------------
CREATE TABLE listings (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  seller_id       uuid NOT NULL,
  category_id     uuid NOT NULL REFERENCES categories (id),
  title           text NOT NULL CHECK (char_length(btrim(title)) BETWEEN 3 AND 140),
  description     text NOT NULL DEFAULT '' CHECK (char_length(description) <= 5000),
  price_minor     bigint NOT NULL CONSTRAINT listings_price_positive CHECK (price_minor > 0),
  currency        char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  stock_quantity  integer NOT NULL CONSTRAINT listings_stock_nonneg CHECK (stock_quantity >= 0),
  status          listing_status NOT NULL DEFAULT 'draft',
  -- cached aggregate of reviews (sum + count, never a decimal average)
  rating_sum      bigint  NOT NULL DEFAULT 0,
  rating_count    integer NOT NULL DEFAULT 0,
  search_tsv      tsvector GENERATED ALWAYS AS
                    (to_tsvector('simple', title || ' ' || description)) STORED,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  deleted_at      timestamptz,
  -- a listing is priced in its seller's currency (composite FK keeps the copy honest)
  CONSTRAINT listings_seller_currency_fk FOREIGN KEY (seller_id, currency)
    REFERENCES sellers (id, currency),
  CONSTRAINT listings_id_seller_currency_uq UNIQUE (id, seller_id, currency),
  CONSTRAINT listings_rating_aggregate_sane CHECK (
    rating_count >= 0 AND rating_sum >= rating_count AND rating_sum <= 5 * rating_count),
  CONSTRAINT listings_timestamps_ordered CHECK (updated_at >= created_at)
);
-- browse by category, newest first / cheapest first (live, active rows only)
CREATE INDEX listings_browse_new_idx   ON listings (category_id, created_at DESC, id DESC)
  WHERE status = 'active' AND deleted_at IS NULL;
CREATE INDEX listings_browse_price_idx ON listings (category_id, price_minor, id)
  WHERE status = 'active' AND deleted_at IS NULL;
-- keyword search
CREATE INDEX listings_search_gin ON listings USING gin (search_tsv)
  WHERE status = 'active' AND deleted_at IS NULL;
-- a seller's own catalogue
CREATE INDEX listings_seller_idx ON listings (seller_id, created_at DESC, id DESC)
  WHERE deleted_at IS NULL;

CREATE FUNCTION listings_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE s sellers%ROWTYPE;
BEGIN
  SELECT * INTO s FROM sellers WHERE id = NEW.seller_id;
  IF TG_OP = 'INSERT' THEN
    IF s.deleted_at IS NOT NULL THEN
      RAISE EXCEPTION 'seller % is closed', s.id USING ERRCODE = 'DK003';
    END IF;
  ELSE
    IF NEW.seller_id <> OLD.seller_id OR NEW.currency <> OLD.currency THEN
      RAISE EXCEPTION 'listing seller/currency are immutable' USING ERRCODE = 'DK002';
    END IF;
    PERFORM assert_transition('listing', OLD.status::text, NEW.status::text);
  END IF;
  IF NEW.status = 'active' AND s.status <> 'active' AND
     (TG_OP = 'INSERT' OR OLD.status <> 'active') THEN
    RAISE EXCEPTION 'seller % is % and cannot activate listings', s.id, s.status
      USING ERRCODE = 'DK003';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER listings_10_initial BEFORE INSERT ON listings
  FOR EACH ROW EXECUTE FUNCTION enforce_initial_status('draft');
CREATE TRIGGER listings_20_guard BEFORE INSERT OR UPDATE ON listings
  FOR EACH ROW EXECUTE FUNCTION listings_guard();
CREATE TRIGGER listings_90_updated_at BEFORE UPDATE ON listings
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------- orders (one buyer, one seller) --------------------------
CREATE TABLE orders (
  id                 uuid PRIMARY KEY DEFAULT uuidv7(),
  -- human-facing reference: random, so it leaks neither volume nor ordering
  order_number       text NOT NULL UNIQUE
                       DEFAULT 'DK-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12)),
  buyer_id           uuid NOT NULL REFERENCES users (id),
  seller_id          uuid NOT NULL,
  status             order_status NOT NULL DEFAULT 'pending_payment',
  currency           char(3) NOT NULL,
  items_subtotal_minor bigint NOT NULL DEFAULT 0 CHECK (items_subtotal_minor >= 0),  -- maintained by trigger
  shipping_fee_minor bigint NOT NULL DEFAULT 0 CHECK (shipping_fee_minor >= 0),
  total_minor        bigint GENERATED ALWAYS AS (items_subtotal_minor + shipping_fee_minor) STORED,
  shipping_address_id uuid NOT NULL,
  -- snapshots, filled by trigger so a client cannot forge them
  seller_shop_name_snapshot text NOT NULL,
  ship_recipient     text NOT NULL,
  ship_line1         text NOT NULL,
  ship_line2         text,
  ship_city          text NOT NULL,
  ship_region        text,
  ship_postal_code   text NOT NULL,
  ship_country       char(2) NOT NULL,
  carrier            text,
  tracking_number    text,
  paid_at            timestamptz,
  shipped_at         timestamptz,
  delivered_at       timestamptz,
  completed_at       timestamptz,
  cancelled_at       timestamptz,
  cancelled_by       actor_kind,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT orders_seller_currency_fk FOREIGN KEY (seller_id, currency) REFERENCES sellers (id, currency),
  CONSTRAINT orders_ship_address_belongs_to_buyer FOREIGN KEY (shipping_address_id, buyer_id)
    REFERENCES addresses (id, user_id),
  CONSTRAINT orders_id_seller_currency_uq UNIQUE (id, seller_id, currency),
  CONSTRAINT orders_id_currency_uq        UNIQUE (id, currency),
  CONSTRAINT orders_id_buyer_status_uq    UNIQUE (id, buyer_id, status),
  CONSTRAINT orders_shipped_has_tracking CHECK (
    status NOT IN ('shipped', 'delivered', 'completed')
    OR (shipped_at IS NOT NULL AND tracking_number IS NOT NULL AND carrier IS NOT NULL)),
  CONSTRAINT orders_paid_has_paid_at CHECK (status = 'pending_payment' OR status = 'cancelled' OR paid_at IS NOT NULL),
  CONSTRAINT orders_delivered_has_delivered_at CHECK (
    status NOT IN ('delivered', 'completed', 'refunded') OR delivered_at IS NOT NULL),
  CONSTRAINT orders_completed_has_completed_at CHECK (status <> 'completed' OR completed_at IS NOT NULL),
  CONSTRAINT orders_cancelled_has_cancel_info CHECK (
    status <> 'cancelled' OR (cancelled_at IS NOT NULL AND cancelled_by IS NOT NULL)),
  CONSTRAINT orders_timestamps_ordered CHECK (
    updated_at >= created_at
    AND (paid_at      IS NULL OR paid_at      >= created_at)
    AND (shipped_at   IS NULL OR shipped_at   >= paid_at)
    AND (delivered_at IS NULL OR delivered_at >= shipped_at)
    AND (completed_at IS NULL OR completed_at >= delivered_at))
);
CREATE INDEX orders_buyer_history_idx ON orders (buyer_id, created_at DESC, id DESC);
CREATE INDEX orders_seller_history_idx ON orders (seller_id, created_at DESC, id DESC);
CREATE INDEX orders_fulfilment_queue_idx ON orders (seller_id, created_at, id) WHERE status = 'paid';
CREATE INDEX orders_pending_expiry_idx ON orders (created_at) WHERE status = 'pending_payment';

-- append-only audit of every status change
CREATE TABLE order_events (
  id          uuid PRIMARY KEY DEFAULT uuidv7(),
  order_id    uuid NOT NULL REFERENCES orders (id),
  from_status order_status,
  to_status   order_status NOT NULL,
  actor_type  actor_kind NOT NULL,
  actor_id    uuid,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX order_events_order_idx ON order_events (order_id, created_at);
CREATE FUNCTION forbid_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE = 'DK002';
END $$;
CREATE TRIGGER order_events_append_only BEFORE UPDATE OR DELETE ON order_events
  FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- ---------- order_items (orders M:N listings) -----------------------
CREATE TABLE order_items (
  id                 uuid PRIMARY KEY DEFAULT uuidv7(),
  order_id           uuid NOT NULL,
  listing_id         uuid NOT NULL,
  seller_id          uuid NOT NULL,                 -- copied from listing, FK-verified against BOTH parents
  currency           char(3) NOT NULL,
  quantity           integer NOT NULL CHECK (quantity BETWEEN 1 AND 999),
  unit_price_minor   bigint NOT NULL CHECK (unit_price_minor > 0),   -- price AT PURCHASE
  title_snapshot     text NOT NULL,                                  -- title AT PURCHASE
  line_total_minor   bigint GENERATED ALWAYS AS (quantity * unit_price_minor) STORED,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT order_items_order_fk   FOREIGN KEY (order_id, seller_id, currency)
    REFERENCES orders (id, seller_id, currency),
  CONSTRAINT order_items_listing_fk FOREIGN KEY (listing_id, seller_id, currency)
    REFERENCES listings (id, seller_id, currency),
  CONSTRAINT order_items_one_line_per_listing UNIQUE (order_id, listing_id),
  CONSTRAINT order_items_id_order_listing_uq UNIQUE (id, order_id, listing_id),
  CONSTRAINT order_items_timestamps_ordered CHECK (updated_at >= created_at)
);
-- Listing-side lookups (e.g. "orders containing this listing") are not an API
-- query in v1, and listings are never hard-deleted, so no index on listing_id.

CREATE FUNCTION order_items_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE o orders%ROWTYPE; l listings%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'order_items are immutable once written' USING ERRCODE = 'DK002';
  END IF;
  SELECT * INTO o FROM orders WHERE id = NEW.order_id FOR UPDATE;
  IF o.status <> 'pending_payment' THEN
    RAISE EXCEPTION 'cannot add items to an order in status %', o.status USING ERRCODE = 'DK003';
  END IF;
  IF EXISTS (SELECT 1 FROM payments WHERE order_id = NEW.order_id) THEN
    RAISE EXCEPTION 'cannot add items after payment was initiated' USING ERRCODE = 'DK003';
  END IF;
  SELECT * INTO l FROM listings WHERE id = NEW.listing_id;
  IF l.status <> 'active' OR l.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'listing % is not available', l.id USING ERRCODE = 'DK003';
  END IF;
  -- snapshot price/title from the listing; client-supplied values are overwritten
  NEW.seller_id        := l.seller_id;
  NEW.currency         := l.currency;
  NEW.unit_price_minor := l.price_minor;
  NEW.title_snapshot   := l.title;
  RETURN NEW;
END $$;
CREATE TRIGGER order_items_10_guard BEFORE INSERT OR UPDATE OR DELETE ON order_items
  FOR EACH ROW EXECUTE FUNCTION order_items_guard();

-- reserve stock + keep orders.items_subtotal_minor equal to sum(line totals)
CREATE FUNCTION order_items_after_insert() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE listings SET stock_quantity = stock_quantity - NEW.quantity WHERE id = NEW.listing_id;
  UPDATE orders   SET items_subtotal_minor = items_subtotal_minor + NEW.line_total_minor
   WHERE id = NEW.order_id;
  RETURN NULL;
END $$;
CREATE TRIGGER order_items_20_reserve AFTER INSERT ON order_items
  FOR EACH ROW EXECUTE FUNCTION order_items_after_insert();

-- ---------- payments -------------------------------------------------
CREATE TABLE payments (
  id                 uuid PRIMARY KEY DEFAULT uuidv7(),
  order_id           uuid NOT NULL,
  currency           char(3) NOT NULL,
  amount_minor       bigint NOT NULL CHECK (amount_minor > 0),
  status             payment_status NOT NULL DEFAULT 'pending',
  provider           text NOT NULL,
  provider_reference text,
  failure_code       text,
  captured_at        timestamptz,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT payments_order_currency_fk FOREIGN KEY (order_id, currency) REFERENCES orders (id, currency),
  CONSTRAINT payments_failed_has_code CHECK (status <> 'failed' OR failure_code IS NOT NULL),
  CONSTRAINT payments_captured_has_ts CHECK (status NOT IN ('captured', 'refunded') OR captured_at IS NOT NULL),
  CONSTRAINT payments_timestamps_ordered CHECK (updated_at >= created_at)
);
-- at most one payment that is in flight or has succeeded per order (failed attempts may pile up)
CREATE UNIQUE INDEX payments_one_live_per_order ON payments (order_id)
  WHERE status IN ('pending', 'authorized', 'captured');
CREATE UNIQUE INDEX payments_provider_ref_uq ON payments (provider, provider_reference)
  WHERE provider_reference IS NOT NULL;
CREATE INDEX payments_order_idx ON payments (order_id, created_at);

CREATE FUNCTION payments_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE o orders%ROWTYPE;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO o FROM orders WHERE id = NEW.order_id FOR UPDATE;
    IF o.status <> 'pending_payment' THEN
      RAISE EXCEPTION 'order % is % and cannot take a new payment', o.id, o.status USING ERRCODE = 'DK003';
    END IF;
    IF NEW.amount_minor <> o.total_minor THEN
      RAISE EXCEPTION 'payment amount % != order total %', NEW.amount_minor, o.total_minor
        USING ERRCODE = 'DK003';
    END IF;
  ELSE
    IF NEW.order_id <> OLD.order_id OR NEW.amount_minor <> OLD.amount_minor
       OR NEW.currency <> OLD.currency THEN
      RAISE EXCEPTION 'payment order/amount/currency are immutable' USING ERRCODE = 'DK002';
    END IF;
    PERFORM assert_transition('payment', OLD.status::text, NEW.status::text);
    IF NEW.status = 'captured' AND OLD.status <> 'captured' THEN
      NEW.captured_at := COALESCE(NEW.captured_at, now());
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER payments_10_initial BEFORE INSERT ON payments
  FOR EACH ROW EXECUTE FUNCTION enforce_initial_status('pending');
CREATE TRIGGER payments_20_guard BEFORE INSERT OR UPDATE ON payments
  FOR EACH ROW EXECUTE FUNCTION payments_guard();
CREATE TRIGGER payments_90_updated_at BEFORE UPDATE ON payments
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- provider webhooks: the provider's event id is the idempotency key
CREATE TABLE payment_events (
  provider_event_id text PRIMARY KEY,
  payment_id        uuid NOT NULL REFERENCES payments (id),
  event_type        text NOT NULL,
  payload           jsonb NOT NULL,
  created_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX payment_events_payment_idx ON payment_events (payment_id);

-- ---------- order guard (now that payments exists) ------------------
CREATE FUNCTION orders_before_insert() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE s sellers%ROWTYPE; a addresses%ROWTYPE;
BEGIN
  SELECT * INTO s FROM sellers WHERE id = NEW.seller_id;
  IF s.status <> 'active' OR s.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'seller % is not accepting orders', s.id USING ERRCODE = 'DK003';
  END IF;
  IF s.user_id = NEW.buyer_id THEN
    RAISE EXCEPTION 'a seller cannot buy from their own shop' USING ERRCODE = 'DK003';
  END IF;
  SELECT * INTO a FROM addresses WHERE id = NEW.shipping_address_id;
  IF a.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'address % was deleted', a.id USING ERRCODE = 'DK003';
  END IF;
  NEW.seller_shop_name_snapshot := s.shop_name;
  NEW.shipping_fee_minor := s.flat_shipping_fee_minor;   -- fee is snapshotted from the shop at order time
  NEW.ship_recipient   := a.recipient_name;
  NEW.ship_line1       := a.line1;
  NEW.ship_line2       := a.line2;
  NEW.ship_city        := a.city;
  NEW.ship_region      := a.region;
  NEW.ship_postal_code := a.postal_code;
  NEW.ship_country     := a.country;
  NEW.items_subtotal_minor := 0;
  RETURN NEW;
END $$;
CREATE TRIGGER orders_10_initial BEFORE INSERT ON orders
  FOR EACH ROW EXECUTE FUNCTION enforce_initial_status('pending_payment');
CREATE TRIGGER orders_20_before_insert BEFORE INSERT ON orders
  FOR EACH ROW EXECUTE FUNCTION orders_before_insert();

CREATE FUNCTION orders_before_update() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  -- columns that may legitimately change after creation
  mutable_cols text[] := ARRAY['status','updated_at','paid_at','shipped_at','delivered_at',
                               'completed_at','cancelled_at','cancelled_by','carrier',
                               'tracking_number','items_subtotal_minor','total_minor'];
  erasure_cols text[] := ARRAY['ship_recipient','ship_line1','ship_line2','ship_city',
                               'ship_region','ship_postal_code','ship_country'];
  erasing boolean := coalesce(current_setting('app.erasure', true), '') = 'on';
BEGIN
  -- 1. is this status change on the allowed-transition list? (checked first so that
  --    "completed -> shipped" reports an illegal transition, not just "read-only")
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    PERFORM assert_transition('order', OLD.status::text, NEW.status::text);
  END IF;
  -- 2. everything outside the mutable list is frozen (ids, buyer, seller, currency, fee, snapshots)
  IF (to_jsonb(NEW) - mutable_cols - CASE WHEN erasing THEN erasure_cols ELSE '{}' END)
     IS DISTINCT FROM
     (to_jsonb(OLD) - mutable_cols - CASE WHEN erasing THEN erasure_cols ELSE '{}' END) THEN
    RAISE EXCEPTION 'order % has frozen columns that cannot change', OLD.id USING ERRCODE = 'DK002';
  END IF;
  IF NEW.items_subtotal_minor <> OLD.items_subtotal_minor AND OLD.status <> 'pending_payment' THEN
    RAISE EXCEPTION 'order totals are frozen once the order leaves pending_payment' USING ERRCODE = 'DK002';
  END IF;
  -- terminal orders do not change at all (apart from erasure of the ship-to snapshot)
  IF OLD.status IN ('completed', 'cancelled', 'refunded') AND
     (to_jsonb(NEW) - 'updated_at' - 'total_minor' - erasure_cols)
       IS DISTINCT FROM (to_jsonb(OLD) - 'updated_at' - 'total_minor' - erasure_cols) THEN
    RAISE EXCEPTION 'order % is % and is read-only', OLD.id, OLD.status USING ERRCODE = 'DK002';
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'paid' AND NOT EXISTS (
         SELECT 1 FROM payments WHERE order_id = NEW.id AND status = 'captured') THEN
      RAISE EXCEPTION 'order % cannot be paid without a captured payment', NEW.id USING ERRCODE = 'DK003';
    END IF;
    IF NEW.status = 'paid' AND NEW.items_subtotal_minor = 0 THEN
      RAISE EXCEPTION 'order % has no items', NEW.id USING ERRCODE = 'DK003';
    END IF;
    IF NEW.status = 'refunded' AND NOT EXISTS (
         SELECT 1 FROM payments WHERE order_id = NEW.id AND status = 'refunded') THEN
      RAISE EXCEPTION 'order % cannot be refunded before its payment is refunded', NEW.id USING ERRCODE = 'DK003';
    END IF;
    NEW.paid_at      := CASE WHEN NEW.status = 'paid'      THEN COALESCE(NEW.paid_at, now())      ELSE NEW.paid_at END;
    NEW.shipped_at   := CASE WHEN NEW.status = 'shipped'   THEN COALESCE(NEW.shipped_at, now())   ELSE NEW.shipped_at END;
    NEW.delivered_at := CASE WHEN NEW.status = 'delivered' THEN COALESCE(NEW.delivered_at, now()) ELSE NEW.delivered_at END;
    NEW.completed_at := CASE WHEN NEW.status = 'completed' THEN COALESCE(NEW.completed_at, now()) ELSE NEW.completed_at END;
    NEW.cancelled_at := CASE WHEN NEW.status = 'cancelled' THEN COALESCE(NEW.cancelled_at, now()) ELSE NEW.cancelled_at END;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER orders_20_before_update BEFORE UPDATE ON orders
  FOR EACH ROW EXECUTE FUNCTION orders_before_update();
CREATE TRIGGER orders_90_updated_at BEFORE UPDATE ON orders
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- audit trail + restock on cancel
CREATE FUNCTION orders_after_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO order_events (order_id, from_status, to_status, actor_type, actor_id)
    VALUES (NEW.id,
            CASE WHEN TG_OP = 'UPDATE' THEN OLD.status END,
            NEW.status,
            coalesce(nullif(current_setting('app.actor_type', true), ''), 'system')::actor_kind,
            nullif(current_setting('app.actor_id', true), '')::uuid);
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.status = 'cancelled' AND OLD.status <> 'cancelled' THEN
    UPDATE listings l SET stock_quantity = l.stock_quantity + oi.quantity
      FROM order_items oi
     WHERE oi.order_id = NEW.id AND l.id = oi.listing_id;
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER orders_30_after_change AFTER INSERT OR UPDATE ON orders
  FOR EACH ROW EXECUTE FUNCTION orders_after_change();

-- ---------- reviews --------------------------------------------------
CREATE TABLE reviews (
  id             uuid PRIMARY KEY DEFAULT uuidv7(),
  order_id       uuid NOT NULL,
  order_item_id  uuid NOT NULL,
  listing_id     uuid NOT NULL,
  buyer_id       uuid NOT NULL,
  -- Constant column that exists only to make the FK below demand status = 'completed'.
  order_status   order_status NOT NULL DEFAULT 'completed'
                   CONSTRAINT reviews_order_must_be_completed CHECK (order_status = 'completed'),
  rating         smallint NOT NULL CONSTRAINT reviews_rating_range CHECK (rating BETWEEN 1 AND 5),
  body           text CHECK (body IS NULL OR char_length(body) <= 2000),
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  deleted_at     timestamptz,
  CONSTRAINT reviews_item_fk  FOREIGN KEY (order_item_id, order_id, listing_id)
    REFERENCES order_items (id, order_id, listing_id),
  CONSTRAINT reviews_order_completed_fk FOREIGN KEY (order_id, buyer_id, order_status)
    REFERENCES orders (id, buyer_id, status),
  CONSTRAINT reviews_one_per_item UNIQUE (order_item_id),
  CONSTRAINT reviews_timestamps_ordered CHECK (updated_at >= created_at)
);
CREATE INDEX reviews_listing_idx ON reviews (listing_id, created_at DESC, id DESC) WHERE deleted_at IS NULL;

CREATE FUNCTION reviews_before_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (to_jsonb(NEW) - 'body' - 'deleted_at' - 'updated_at') IS DISTINCT FROM
     (to_jsonb(OLD) - 'body' - 'deleted_at' - 'updated_at') THEN
    RAISE EXCEPTION 'only a review''s body can be edited' USING ERRCODE = 'DK002';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER reviews_10_guard BEFORE UPDATE ON reviews
  FOR EACH ROW EXECUTE FUNCTION reviews_before_update();
CREATE TRIGGER reviews_90_updated_at BEFORE UPDATE ON reviews
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- keep listings.rating_sum / rating_count equal to the live reviews
CREATE FUNCTION reviews_aggregate() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.deleted_at IS NULL THEN
    UPDATE listings SET rating_sum = rating_sum + NEW.rating, rating_count = rating_count + 1
     WHERE id = NEW.listing_id;
  ELSIF TG_OP = 'UPDATE' AND OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN
    UPDATE listings SET rating_sum = rating_sum - OLD.rating, rating_count = rating_count - 1
     WHERE id = NEW.listing_id;
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER reviews_20_aggregate AFTER INSERT OR UPDATE ON reviews
  FOR EACH ROW EXECUTE FUNCTION reviews_aggregate();

-- ---------- idempotency keys (hard-deleted after TTL) ---------------
CREATE TABLE idempotency_keys (
  principal_id   uuid NOT NULL,                -- the authenticated user; keys are per-caller
  idem_key       text NOT NULL CHECK (char_length(idem_key) BETWEEN 8 AND 128),
  request_method text NOT NULL,
  request_path   text NOT NULL,
  request_hash   text NOT NULL,                -- sha256 of the body; same key + different body = 422
  response_status integer,                     -- NULL while the first request is still running
  response_body  jsonb,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  expires_at     timestamptz NOT NULL DEFAULT now() + interval '24 hours',
  PRIMARY KEY (principal_id, idem_key)
);
CREATE INDEX idempotency_keys_expiry_idx ON idempotency_keys (expires_at);

-- ---------- erasure ---------------------------------------------------
-- Compliance: financial records (orders, payments, events) are retained; the
-- personal data on them is destroyed. Refuses while the user has money in flight.
CREATE FUNCTION anonymise_user(p_user uuid) RETURNS void LANGUAGE plpgsql AS $$
DECLARE v_seller uuid;
BEGIN
  SELECT id INTO v_seller FROM sellers WHERE user_id = p_user;
  IF EXISTS (SELECT 1 FROM orders
              WHERE (buyer_id = p_user OR seller_id = v_seller)
                AND status IN ('pending_payment', 'paid', 'shipped', 'delivered')) THEN
    RAISE EXCEPTION 'user % has open orders; erasure refused', p_user USING ERRCODE = 'DK003';
  END IF;
  PERFORM set_config('app.erasure', 'on', true);
  UPDATE orders SET ship_recipient = '[erased]', ship_line1 = '[erased]', ship_line2 = NULL,
                    ship_city = '[erased]', ship_region = NULL, ship_postal_code = '[erased]'
   WHERE buyer_id = p_user;
  UPDATE addresses SET recipient_name = '[erased]', line1 = '[erased]', line2 = NULL, city = '[erased]',
                       region = NULL, postal_code = '[erased]', phone_e164 = NULL,
                       is_default = false, deleted_at = now()
   WHERE user_id = p_user;
  IF v_seller IS NOT NULL THEN
    UPDATE listings SET deleted_at = now() WHERE seller_id = v_seller AND deleted_at IS NULL;
    UPDATE sellers  SET shop_name = '[closed shop]', shop_slug = 'closed-' || id::text,
                        status = 'suspended', deleted_at = now() WHERE id = v_seller;
  END IF;
  UPDATE users SET email = NULL, full_name = NULL, phone_e164 = NULL, deleted_at = now() WHERE id = p_user;
END $$;

COMMIT;
